#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { useParent } from '../settings/settings';
import { sheetKey, useSheet } from './sheet';
import type { Sheet } from './sheet';

/** The sheet's today: shown, and changeable. Changing it re-reads everything under the sheet. Also whether the
 *  sheet is archived, and its parent sheet (nothing when none), and the button a steward archives it with; both share the sheet's one error. */
function SheetToday({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const sheet = useSheet(sheetId);
  const parent = useParent(sheetId);
  const [typed, setTyped] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (today: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { user, today }),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetKey(sheetId), saved);
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onSettled: once.done,
  });

  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, { user }),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetKey(sheetId), saved);
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!once.start()) return;
    save.reset();
    archive.reset();
    save.mutate(typed.trim());
  };

  return (
    <section>
      <p>
        Today <strong data-testid="sheet-today">{sheet.data?.today ?? ''}</strong>
      </p>
      <form data-testid="sheet-today-form" onSubmit={submit}>
        <label>
          Change today{' '}
          <input
            data-testid="sheet-today-input"
            placeholder="yyyy-mm-dd"
            value={typed}
            onChange={(e) => {
              setTyped(e.target.value);
              save.reset();
              archive.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
          Set today
        </button>
      </form>
      <p>
        Parent <strong data-testid="sheet-parent">{parent}</strong>{' '}
        Archived <strong data-testid="sheet-archived">{sheet.data ? (sheet.data.archived ? 'yes' : 'no') : ''}</strong>{' '}
        <button
          type="button"
          data-testid="sheet-archive"
          disabled={archive.isPending}
          onClick={() => {
            if (!once.start()) return;
            save.reset();
            archive.reset();
            archive.mutate();
          }}
        >
          Archive sheet
        </button>
      </p>
      {(save.isError || archive.isError) && (
        <p data-testid="sheet-error" role="alert">
          {archive.isError
            ? archive.error instanceof HttpError && archive.error.body
              ? archive.error.body
              : 'Could not archive the sheet.'
            : save.error instanceof HttpError && save.error.status === 403 && save.error.body
              ? save.error.body
              : 'Could not change today: enter a real date as yyyy-mm-dd.'}
        </p>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 0, Component: SheetToday });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';

/** A sheet: its id, its today (ISO yyyy-mm-dd) and whether it is archived (every change refused). */
export type Sheet = { id: string; today: string; archived: boolean };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'meta'] as const;

export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/** The date this user's screen shows the sheet as of (yyyy-mm-dd; '' when it shows it as it is now). It belongs to
 *  the screen, not the sheet: other users are unaffected. While it is set, everything under the sheet is read as it
 *  stood at the end of that day, and every change is refused. */
export function useAsOf() {
  return useSearchParam('asOf', asString);
}

/**
 * The sheet's today — the date every date-dependent decision and every default date on the sheet
 * uses. Never read the real clock (`new Date()`) for these; use this instead. '' while loading.
 * While the screen shows the sheet as of a date, that date stands in for it.
 */
export function useSheetToday(sheetId: string): string {
  const [asOf] = useAsOf();
  const today = useSheet(sheetId).data?.today ?? '';
  return asOf !== '' && today !== '' ? asOf : today;
}
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's body. Every feature kept per sheet contributes here; the home page renders it
 * only once someone is signed in and a sheet is loaded. Server data under a sheet is keyed
 * ['sheet', sheetId, ...] so a sheet load re-reads all of it.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');

