package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;

/** A validated settings save: who is making it, and the settings it changes, in order — whether it sets the clerk
 *  limit and to what (two decimals; null: no limit), and the floor it sets (two decimals; null: left as it is) and the terms it sets (days; null: left as it is) and the late percent it sets (two decimals; null: left as it is), and whether it sets the policy date and to what (null: blank, the sheet's today), and whether it sets the period numbering from and to what (null: blank, off), and the grades whose own terms it sets
 *  (A, B, C order) and to what (days; null: none, the sheet's terms), and whether it sets the cap and to what (two
 *  decimals; null: none), and the from-dates given for the dated ones it sets, by key (one not given: from the sheet's
 *  today), and whether it sets the proof threshold and to what (two decimals; null: none), and the permission entries it sets
 *  (in action order) and to what (roles comma separated; '': the standing rule), and whether it sets the grace days and to what (days; null: off), and whether it sets the note threshold and to what (two decimals; null: none), and whether it sets the entry date and to what (null: blank, off), and the grades whose grace it sets (A, B, C order) and to what (days; null: none), and the grades whose own proof threshold it sets (A, B, C order) and to what (two decimals; null: none, the sheet's), and whether it sets the pot and to what (two decimals; null: none), and whether it sets the parent sheet and to what (a sheet id; null: none). */
public record SettingsInput(String user, boolean setsClerkLimit, BigDecimal clerkLimit, BigDecimal floor,
        Integer terms, BigDecimal latePct, boolean setsPolicyDate, LocalDate policyDate,
        boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom,
        Map<String, Integer> gradeTerms, boolean setsCap, BigDecimal cap,
        Map<String, LocalDate> from, boolean setsProofThreshold, BigDecimal proofThreshold,
        Map<String, String> perms, boolean setsGraceDays, Integer graceDays,
        boolean setsNoteThreshold, BigDecimal noteThreshold,
        boolean setsEntryDate, LocalDate entryDate, Map<String, Integer> gradeGrace,
        Map<String, BigDecimal> gradeProofThreshold, boolean setsPot, BigDecimal pot,
        boolean setsParent, String parent) {
}
package net.officefloor.hq.app.role;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Roles by sheet: at most one per user name; a name with none is a clerk. */
@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, i) -> new Role(rs.getString("sheet_id"),
            rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's assigned roles, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT * FROM sheet_role WHERE sheet_id = ? ORDER BY user_name", ROW, sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force by the sheet's
     *  today, else the one assigned. */
    public String of(String sheetId, String user) {
        Integer delegated = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_delegation d JOIN sheet s "
                + "ON s.id = d.sheet_id WHERE d.sheet_id = ? AND d.user_name = ? "
                + "AND s.today BETWEEN d.from_date AND d.to_date", Integer.class, sheetId, user);
        return delegated != null && delegated > 0 ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's assigned role on the sheet: the one assigned, else clerk. */
    public String assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : found.get(0);
    }

    /** Assign the user's role on the sheet, replacing any they had. */
    public Role set(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role KEY (sheet_id, user_name) VALUES (?, ?, ?)", sheetId, user, role);
        return new Role(sheetId, user, role);
    }
}
